message.content:
{
  "unit_id": "p2",
  "status": "REVIEWED",
  "reason": "Inventory of explicit directives in p2, retaining parent/neighbor context from p1 and p3. Shared conditions (e.g., status checks, payment method constraints) and exceptions (e.g., gift card balance requirements) are preserved. Unresolved cross-references (e.g., tool descriptions in p3) are marked as UNKNOWN or open_questions. Disjunctions are treated as single requirements.",
  "requirements": [
    {
      "local_id": "req_modify_payment_pending",
      "action": "modify payment method",
      "action_spans": [
        {"source_id": "p2", "quote": "The user can only choose a single payment method different from the original payment method."}
      ],
      "scope": "pending order",
      "source_spans": [
        {"source_id": "p1", "quote": "Generally, you can only take action on pending or delivered orders."},
        {"source_id": "p2", "quote": "After user confirmation, the order status will be kept as 'pending'."}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "modify_payment_condition",
        "spans": [
          {"source_id": "p2", "quote": "The user can only choose a single payment method different from the original payment method."}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "status_check",
            "spans": [
              {"source_id": "p1", "quote": "An order can only be cancelled if its status is 'pending'"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "gift_card_balance",
            "spans": [
              {"source_id": "p2", "quote": "it must have enough balance to cover the total amount."}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "user_confirmation",
        "spans": [
          {"source_id": "p2", "quote": "After user confirmation"}
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "OR",
          "label": "refund_exceptions",
          "spans": [
            {"source_id": "p2", "quote": "The original payment method will be refunded immediately if it is a gift card"}
          ],
          "children": [
            {
              "op": "ATOM",
              "label": "gift_card_refund",
              "spans": [
                {"source_id": "p2", "quote": "immediately if it is gift card"}
              ],
              "children": []
            },
            {
              "op": "ATOM",
              "label": "other_payment_refund",
              "spans": [
                {"source_id": "p2", "quote": "otherwise it will be refunded within 5 to 7 business days."}
              ],
              "children": []
            }
          ]
        }
      ],
      "open_questions": [
        "Is there a mechanism to verify the gift card balance before modification?"
      ]
    },
    {
      "local_id": "req_modify_items_pending",
      "action": "modify items in pending order",
      "action_spans": [
        {"source_id": "p2", "quote": "For a pending order, each item can be modified to an available new item of the same product but of different product option."}
      ],
      "scope": "pending order (items modifiable)",
      "source_spans": [
        {"source_id": "p1", "quote": "An order can only be modified if its status is 'pending'"},
        {"source_id": "p2", "quote": "The agent will not be able to modify or cancel the order anymore."}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "modify_items_condition",
        "spans": [
          {"source_id": "p2", "quote": "This action can only be called once"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "status_check",
            "spans": [
              {"source_id": "p1", "quote": "An order can only be modified if its status is 'pending'"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "same_product_type",
            "spans": [
              {"source_id": "p2", "quote": "There cannot be any change of product types, e.g. modify shirt to shoe."}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "gift_card_balance_difference",
            "spans": [
              {"source_id": "p3", "quote": "If the user provides a gift card, it must have enough balance to cover the price difference."}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "user_confirmation",
        "spans": [
          {"source_id": "p2", "quote": "you must confirm all the details are correct"}
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "ATOM",
          "label": "status_change",
          "spans": [
            {"source_id": "p2", "quote": "The order status will be changed to 'pending (items modified)'"}
          ],
          "children": []
        }
      ],
      "open_questions": [
        "What happens if the user does not provide a payment method for price difference?",
        "Is there a tool to verify item availability before modification?"
      ]
    },
    {
      "local_id": "req_return_delivered_order",
      "action": "return delivered order",
      "action_spans": [
        {"source_id": "p2", "quote": "An order can only be returned if its status is 'delivered'"}
      ],
      "scope": "delivered order",
      "source_spans": [
        {"source_id": "p1", "quote": "Generally, you can only take action on pending or delivered orders."},
        {"source_id": "p2", "quote": "After user confirmation, the order status will be changed to 'return requested'"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "return_condition",
        "spans": [
          {"source_id": "p2", "quote": "The user needs to confirm the order id and the list of items to be returned."}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "status_check",
            "spans": [
              {"source_id": "p2", "quote": "An order can only be returned if its status is 'delivered'"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "refund_payment_method",
            "spans": [
              {"source_id": "p2", "quote": "The refund must either go to the original payment method, or an existing gift card."}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "user_confirmation",
        "spans": [
          {"source_id": "p2", "quote": "After user confirmation"}
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "ATOM",
          "label": "status_change",
          "spans": [
            {"source_id": "p2", "quote": "the order status will be changed to 'return requested'"}
          ],
          "children": []
        }
      ],
      "open_questions": [
        "Is there a limit to the number of items that can be returned?",
        "What is the process for handling partial returns?"
      ]
    },
    {
      "local_id": "req_exchange_delivered_order",
      "action": "exchange items in delivered order",
      "action_spans": [
        {"source_id": "p2", "quote": "For a delivered order, each item can be exchanged to an available new item of the same product but of different product option."}
      ],
      "scope": "delivered order (items exchangeable)",
      "source_spans": [
        {"source_id": "p1", "quote": "Generally, you can only take action on pending or delivered orders."},
        {"source_id": "p3", "quote": "There is no need to place a new order."}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "exchange_condition",
        "spans": [
          {"source_id": "p2", "quote": "An order can only be exchanged if its status is 'delivered'"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "status_check",
            "spans": [
              {"source_id": "p2", "quote": "An order can only be exchanged if its status is 'delivered'"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "same_product_type",
            "spans": [
              {"source_id": "p2", "quote": "There cannot be any change of product types, e.g. modify shirt to shoe."}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "gift_card_balance_difference",
            "spans": [
              {"source_id": "p3", "quote": "If the user provides a gift card, it must have enough balance to cover the price difference."}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "user_confirmation",
        "spans": [
          {"source_id": "p2", "quote": "The agent needs to explain the exchange detail and ask for explicit user confirmation (yes/no) to proceed."}
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "ATOM",
          "label": "status_change",
          "spans": [
            {"source_id": "p3", "quote": "the order status will be changed to 'exchange requested'"}
          ],
          "children": []
        }
      ],
      "open_questions": [
        "Is there a tool to verify item availability before exchange?",
        "What happens if the new item is not available at the time of exchange?"
      ]
    },
    {
      "local_id": "req_cancel_pending_order",
      "action": "cancel pending order",
      "action_spans": [
        {"source_id": "p1", "quote": "An order can only be cancelled if its status is 'pending'"}
      ],
      "scope": "pending order",
      "source_spans": [
        {"source_id": "p1", "quote": "The user needs to confirm the order id and the reason (either 'no longer needed' or 'ordered by mistake') for cancellation."}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "cancel_condition",
        "spans": [
          {"source_id": "p1", "quote": "An order can only be cancelled if its status is 'pending'"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "status_check",
            "spans": [
              {"source_id": "p1", "quote": "An order can only be cancelled if its status is 'pending'"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "valid_reason",
            "spans": [
              {"source_id": "p1", "quote": "the reason (either 'no longer needed' or 'ordered by mistake')"}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "user_confirmation",
        "spans": [
          {"source_id": "p1", "quote": "After user confirmation"}
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "OR",
          "label": "refund_exceptions",
          "spans": [
            {"source_id": "p1", "quote": "the total will be refunded via the original payment method immediately if it is gift card"}
          ],
          "children": [
            {
              "op": "ATOM",
              "label": "gift_card_refund",
              "spans": [
                {"source_id": "p1", "quote": "immediately if it is gift card"}
              ],
              "children": []
            },
            {
              "op": "ATOM",
              "label": "other_payment_refund",
              "spans": [
                {"source_id": "p1", "quote": "otherwise in 5 to 7 business days."}
              ],
              "children": []
            }
          ]
        }
      ],
      "open_questions": [
        "Is there a tool to verify the reason for cancellation aligns with the allowed reasons?"
      ]
    },
    {
      "local_id": "req_tool_constraints",
      "action": "UNKNOWN (tool usage)",
      "action_spans": [
        {"source_id": "p3", "quote": "[AVAILABLE TOOLS]"}
      ],
      "scope": "UNKNOWN (tool constraints)",
      "source_spans": [
        {"source_id": "p1", "quote": "Exchange or modify order tools can only be called once per order."},
        {"source_id": "p3", "quote": "For a delivered order, return or exchange can be only done once by the agent."}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "UNKNOWN",
        "label": "tool_constraints",
        "spans": [
          {"source_id": "p1", "quote": "Exchange or modify order tools can only be called once per order."}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What are the exact tool names and their constraints?",
        "Are there any implicit tool constraints not mentioned in the source?"
      ]
    }
  ]
}
